type Status = "todo" | "doing" | "done";
interface Task {
  readonly id: number;
  title: string;
  status: Status;
}
const STATUSES: readonly Status[] = ["todo", "doing", "done"];

function board(tasks: readonly Task[]): string {
  const lines = STATUSES.map((status) => {
    const titles = tasks.filter((t) => t.status === status).map((t) => t.title);
    return `${status}: ${titles.join(", ") || "-"}`;
  });
  return lines.join("\n");
}

console.log(board([
  { id: 1, title: "Buy milk", status: "done" },
  { id: 2, title: "Call Ada", status: "todo" },
  { id: 3, title: "File taxes", status: "todo" },
]));

type Status = "todo" | "doing" | "done";
interface Task {
  readonly id: number;
  title: string;
  status: Status;
}
const tasks: Task[] = [];

function addTask(title: string): Task {
  const task: Task = { id: tasks.length + 1, title, status: "todo" };
  tasks.push(task);
  return task;
}
function moveTask(id: number, status: Status): Task | undefined {
  const task = tasks.find((t) => t.id === id);
  if (task) task.status = status;
  return task;
}

const first = addTask("Buy milk");
addTask("Call Ada");
moveTask(first.id, "done");
console.log(moveTask(2, "doing")?.status, moveTask(99, "done"));
console.log(tasks.map((t) => `${t.id}:${t.status}`));

type Status = "todo" | "doing" | "done";
interface Task {
