function fixSpecifier(spec: string): string {
  if (!spec.startsWith(".")) return spec;
  if (spec.endsWith(".ts")) return spec.slice(0, -3) + ".js";
  if (!spec.endsWith(".js")) return spec + ".js";
  return spec;
}

for (const spec of ["./store", "./format.ts", "./task.js", "@zudojs/schema"]) {
  console.log(fixSpecifier(spec));
}

