function moduleFormat(file: string, packageType: string | undefined): "esm" | "commonjs" {
  if (file.endsWith(".mts")) return "esm";
  if (file.endsWith(".cts")) return "commonjs";
  return packageType === "module" ? "esm" : "commonjs";
}

