type Exports = Record<string, { types: string; import: string }>;

function resolveImport(exportsField: Exports, subpath: string): string {
  const entry = exportsField[subpath];
  if (!entry) throw new Error("ERR_PACKAGE_PATH_NOT_EXPORTED");
  return entry.import;
}

const exportsField: Exports = {
  ".": { types: "./dist/index.d.ts", import: "./dist/index.js" },
};
console.log(resolveImport(exportsField, "."));
try {
  resolveImport(exportsField, "./dist/schemaRoot/index.js");
} catch (error) {
  console.log((error as Error).message);
}

